// 연도 범위 (2024 ~ 현재 연도 + 1)
const getAwardYears = () => {
  const currentYear = new Date().getFullYear();
  const years = [];
  for (let y = 2024; y <= currentYear + 1; y++) {
    years.push(String(y));
  }
  return years;
};

// 상 메타데이터 가져오기 (동적)
const getAwardMeta = (awardSystemSettings, year, awardId) => {
  const yearSettings = awardSystemSettings?.yearlyAwards?.[year];
  if (!yearSettings) return null;
  return yearSettings.find(a => a.id === awardId);
};

// 모든 연도의 상 ID → 메타 매핑 (하위 호환용)
const buildAwardMetaMap = (awardSystemSettings) => {
  const map = {};
  if (!awardSystemSettings?.yearlyAwards) return map;
  for (const [year, awards] of Object.entries(awardSystemSettings.yearlyAwards)) {
    for (const award of awards) {
      if (!map[award.id]) {
        map[award.id] = { label: award.name, color: award.color, icon: award.icon };
      }
    }
  }
  return map;
};

// 레거시 AWARD_META (하위 호환)
const AWARD_META = {
  grand: { label: "대상", color: "#f97316" },
  best_fantasy: { label: "베스트 판타지", color: "#6366f1" },
  best_modern: { label: "베스트 현대", color: "#0ea5e9" },
  best_sf: { label: "베스트 SF", color: "#14b8a6" },
  complete: { label: "완결작 상", color: "#22c55e" },
  pick: { label: "내 취향 추천픽", color: "#ec4899" },
  best_murim: { label: "베스트 무협", color: "#dc2626" },
  best_romance: { label: "베스트 로맨스", color: "#ec4899" },
  rising: { label: "신인상", color: "#8b5cf6" },
};

// 수상 파싱 (동적 상 지원)
function parseAwards(json, awardSystemSettings = null) {
  if (!json) return [];
  try {
    const arr = JSON.parse(json);
    if (!Array.isArray(arr)) return [];
    return arr
      .map((a) => ({
        year: a.year,
        type: a.type,
      }))
      .filter((a) => {
        if (!a.year || !a.type) return false;
        // 동적 설정에서 찾기
        if (awardSystemSettings?.yearlyAwards?.[a.year]) {
          const found = awardSystemSettings.yearlyAwards[a.year].find(aw => aw.id === a.type);
          if (found) return true;
        }
        // 레거시 AWARD_META에서 찾기
        return !!AWARD_META[a.type];
      });
  } catch {
    return [];
  }
}

// 수상 뱃지 컴포넌트 (개선)
const AwardsRow = memo(({ awardsJson, awardSystemSettings }) => {
  const items = parseAwards(awardsJson, awardSystemSettings);
  if (!items.length) return null;
  
  return (
    <View style={{ flexDirection: "row", flexWrap: "wrap", marginTop: 6 }}>
      {items.map((a, idx) => {
        // 동적 설정에서 메타 찾기
        let meta = null;
        if (awardSystemSettings?.yearlyAwards?.[a.year]) {
          const found = awardSystemSettings.yearlyAwards[a.year].find(aw => aw.id === a.type);
          if (found) meta = { label: found.name, color: found.color, icon: found.icon };
        }
        // 없으면 레거시에서 찾기
        if (!meta) meta = AWARD_META[a.type];
        if (!meta) return null;
        
        return (
          <View
            key={`${a.year}-${a.type}-${idx}`}
            style={{
              backgroundColor: meta.color,
              paddingHorizontal: 8,
              paddingVertical: 4,
              borderRadius: 999,
              marginRight: 6,
              marginBottom: 4,
              flexDirection: "row",
              alignItems: "center",
            }}
          >
            {meta.icon && <Text style={{ marginRight: 3 }}>{meta.icon}</Text>}
            <Text style={{ color: "#fff", fontSize: 11, fontWeight: "700" }}>
              {`${a.year} ${meta.label}`}
            </Text>
          </View>
        );
      })}
    </View>
  );
});

