                            <View style={{ backgroundColor: C.primary, paddingHorizontal: 6, paddingVertical: 2, borderRadius: 4, marginLeft: 4 }}>
                              <Text style={{ color: "#fff", fontWeight: "800", fontSize: 11 }}>✓선택</Text>
                            </View>
