      {/* ---- JSON 가져오기 모달 ---- */}
      <Modal
        visible={importOpen}
        animationType="slide"
        onRequestClose={() => {
          setImportOpen(false);
          setImportValidation(null);
        }}
        transparent
      >
        <View
          style={{
            flex: 1,
            backgroundColor: "rgba(0,0,0,0.4)",
            justifyContent: "flex-end",
          }}
        >
          <TouchableOpacity 
            style={{ flex: 1 }} 
            activeOpacity={1} 
            onPress={() => {
              setImportOpen(false);
              setImportValidation(null);
            }} 
          />
          <View
            style={{
              backgroundColor: C.card,
              borderTopLeftRadius: 16,
              borderTopRightRadius: 16,
              padding: 16,
              maxHeight: "85%",
            }}
          >
            <Text
              style={{ fontSize: 18, fontWeight: "800", marginBottom: 8 }}
            >
              JSON 데이터 입력
            </Text>
            <Text style={{ color: C.sub, marginBottom: 12 }}>
              백업한 JSON 데이터를 아래에 붙여넣으세요
            </Text>
            <TextInput
              value={importText}
              onChangeText={(t) => {
                setImportText(t);
                setImportValidation(null); // 텍스트 변경 시 검증 결과 초기화
              }}
              multiline
              placeholder='{"v":9, "N":[...], "M":"..."}'
              placeholderTextColor="#9aa8bd"
              style={{
                backgroundColor: "#f8f9fa",
                borderWidth: 1,
                borderColor: C.line,
                borderRadius: 12,
                padding: 12,
                fontSize: 14,
                color: C.text,
                height: importValidation ? 150 : 250,
                textAlignVertical: "top",
              }}
            />
            
            {/* 검증 결과 표시 */}
            {importValidation && (
              <View style={{
                marginTop: 12,
                padding: 12,
                backgroundColor: importValidation.valid ? "#f0fdf4" : "#fef2f2",
                borderRadius: 12,
                borderWidth: 1,
                borderColor: importValidation.valid ? "#86efac" : "#fecaca",
              }}>
                <Text style={{ 
                  fontWeight: "800", 
                  color: importValidation.valid ? "#166534" : "#991b1b",
                  marginBottom: 6
                }}>
                  {importValidation.valid ? "✅ 검증 성공" : "❌ 검증 실패"}
                </Text>
                
                {importValidation.valid && (
                  <>
                    <Text style={{ color: "#374151", marginBottom: 4 }}>
                      📦 포맷: {importValidation.format}
                    </Text>
                    <Text style={{ color: "#374151", marginBottom: 4 }}>
                      📚 작품: {importValidation.novelCount}개 · 매칭: {importValidation.matchCount}개
                    </Text>
                    <Text style={{ color: "#374151", marginBottom: 4 }}>
                      {importValidation.summary}
                    </Text>
                    
                    {/* 경고 메시지 */}
                    {importValidation.warnings.length > 0 && (
                      <View style={{ marginTop: 6, paddingTop: 6, borderTopWidth: 1, borderTopColor: "#d1d5db" }}>
                        {importValidation.warnings.map((w, i) => (
                          <Text key={i} style={{ color: "#b45309", fontSize: 12 }}>{w}</Text>
                        ))}
                      </View>
                    )}
                    
                    {/* 기능 체크리스트 */}
                    <View style={{ marginTop: 6, paddingTop: 6, borderTopWidth: 1, borderTopColor: "#d1d5db" }}>
                      <Text style={{ fontSize: 11, color: "#6b7280" }}>
                        {importValidation.features.hasElo ? "✓" : "✗"} Elo데이터 {" "}
                        {importValidation.features.hasTimestamps ? "✓" : "✗"} 등록일 {" "}
                        {importValidation.features.hasStatus ? "✓" : "✗"} 읽기상태 {" "}
                        {importValidation.features.hasWorkStatus ? "✓" : "✗"} 작품상태
                      </Text>
                    </View>
                  </>
                )}
                
                {/* 에러 메시지 */}
                {importValidation.errors.length > 0 && (
                  <View>
                    {importValidation.errors.map((e, i) => (
                      <Text key={i} style={{ color: "#991b1b" }}>{e}</Text>
                    ))}
                  </View>
                )}
              </View>
            )}
            
            <View
              style={{ flexDirection: "row", gap: 8, marginTop: 12 }}
            >
              <OutlineButton
                title="🔍 검증"
                onPress={runImportValidation}
                style={{ flex: 1 }}
                color={C.primary}
              />
              <PrimaryButton
                title="가져오기"
                onPress={importJSON}
                style={{ flex: 1, opacity: importValidation?.valid ? 1 : 0.5 }}
                disabled={isLoading || !importValidation?.valid}
              />
            </View>
            <OutlineButton
              title="취소"
              onPress={() => {
                setImportOpen(false);
                setImportText("");
                setImportValidation(null);
              }}
              style={{ marginTop: 8 }}
            />
          </View>
        </View>
      </Modal>

      {/* 🔧 v3.0.6: JSON 내보내기 모달 */}
